"""Structured content for frontier panels 601–606.

The records deliberately keep evidence, boundary, self-critique and collision fields
separate so the builder can audit the V7 page structure before publication.
"""


def item(*, title, en, author, year, latest_year, propose, contest, latest, key,
         context, problem, anomaly, claim, single, mechanism, countertest,
         evidence, headline, evidence_reading, debate, limit, self, failure,
         practice, latest_note, record, gap, interface, shared, opposition,
         third, design, falsifier, pos, family, unit, col_failure, alias):
    return {
        "title": title, "en": en, "author": author, "year": year,
        "latest_year": latest_year, "propose": propose, "contest": contest,
        "latest": latest, "key": key, "context": context, "problem": problem,
        "anomaly": anomaly, "claim": claim, "single": single,
        "mechanism": mechanism, "countertest": countertest,
        "evidence": evidence, "headline": headline,
        "evidence_reading": evidence_reading, "debate": debate, "limit": limit,
        "self": self, "failure": failure, "practice": practice,
        "latest_note": latest_note, "record": record, "gap": gap,
        "interface": interface, "shared": shared, "opposition": opposition,
        "third": third, "design": design, "falsifier": falsifier,
        "col": {
            "位置": f"{pos}——它把“{single}”当成单独够用的那一样",
            "单因": claim[:34],
            "预设": f"〔{family}〕{shared}",
            "量纲": unit,
            "失效": col_failure,
            "自曝": self,
            "空栏": gap,
            "异名": alias,
        },
    }


def citem(*, title, en, author, year, latest_year, propose, contest, latest,
          key, context, claim, evidence, limit, self, practice, gap, interface,
          contrast, design, pos, family, unit, alias):
    """Compact constructor used by the remaining panels; prose stays topic-specific."""
    family_no = int(family.split()[0])
    if pos == "S" or (pos == "D" and family_no % 2 == 0):
        collision_failure = f"当{limit}时，名义覆盖越高，{gap}反而越多"
    else:
        collision_failure = f"若{limit}，该读数只覆盖已登记端，不能外推至{gap}"
    result = item(
        title=title, en=en, author=author, year=year, latest_year=latest_year,
        propose=propose, contest=contest, latest=latest, key=key,
        context=context,
        problem=f"旧框架因此把“{key}”压成身份标签、背景条件或技术附注",
        anomaly=f"{contrast}，而总量或平均值仍可能显示一切正常",
        claim=claim, single=key,
        mechanism=f"{claim}；{key[:8]}必须贯通来源与后果",
        countertest=f"移除“{key}”以后，{contrast}仍不出现",
        evidence=evidence, headline=f"{key}可以由单一总指标代表",
        evidence_reading=f"这些材料支持方向，却也要求把{limit}留在结论边界",
        debate=f"{key}的定义、测量与可迁移范围", limit=limit, self=self,
        failure=f"制度只奖励表面覆盖而不结算{gap}", practice=practice,
        latest_note=f"新的研究把{key}从背景变量改成可审计的机制与责任",
        record=f"{key}在每个阶段怎样改变分母、路径与结果", gap=gap,
        interface=interface, shared=f"{key}在正式记录中出现即可代表其真实作用",
        opposition=contrast, third=gap, design=design,
        falsifier=f"删去{key[:8]}后主要读数不变", pos=pos,
        family=family, unit=unit, col_failure=collision_failure,
        alias=alias,
    )
    result["compact"] = True
    return result


def finalize(panel):
    if "select" in panel:
        panel["items"] = [panel["items"][i] for i in panel.pop("select")]
    refs = []
    for it in panel["items"]:
        for key in ("propose", "contest", "latest"):
            value = it[key]
            if value not in refs:
                refs.append(value)
    panel["refs"] = refs
    panel["tail"] = [
        ("二十年连起来看", panel["closing"][0]),
        ("三个常见误解", panel["closing"][1]),
        ("与相邻领域的接口", panel["closing"][2]),
        ("争议现场", panel["closing"][3]),
        ("往下五年看什么", panel["closing"][4]),
        ("可与哪些领域对撞", panel["closing"][5]),
        ("十条可做的研究命题", panel["research"]),
        ("资料核验", []),
    ]
    return panel


